import{_ as t,o as a,c as r,ag as s}from"./chunks/framework.BSwSpTvy.js";const h=JSON.parse('{"title":"📦 Automated Cross-Platform Releases","description":"","frontmatter":{},"headers":[],"relativePath":"features/releases.md","filePath":"features/releases.md"}'),i={name:"features/releases.md"};function o(n,e,l,d,c,u){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="📦-automated-cross-platform-releases" tabindex="-1">📦 Automated Cross-Platform Releases <a class="header-anchor" href="#📦-automated-cross-platform-releases" aria-label="Permalink to &quot;📦 Automated Cross-Platform Releases&quot;">​</a></h1><p>Maintaining parity with upstream Zed while distributing custom builds is hard. The upstream repository relies on massive internal Namespace runners to bundle their binary assets, creating friction for individual contributors trying to release their forks.</p><p>This repository implements a completely automated, public GitHub Actions CI/CD release pipeline using standard runners (<code>macos-13</code>, <code>macos-14</code>, <code>ubuntu-22.04</code>).</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ol><li><strong>Native Apple Notarization</strong>: The workflow handles the 3-step code signing and external Apple Notarization Server API flow natively. It strips the binaries, extracts debug symbols (<code>sentry-cli</code>), signs the app bundle with the <code>Developer ID Application</code> certificate, and waits for successful external notarization before stapling.</li><li><strong>Parallel Architecture Matrix</strong>: The 150-minute Apple Notarization limits are bypassed by breaking builds into isolated parallel matrices (<code>x86_64</code> and <code>aarch64</code> building concurrently on separate VMs).</li><li><strong>Linux Bundles out-of-the-box</strong>: Using the exact upstream compilation targets, the Linux pipelines output <code>tar.gz</code> and remote server <code>.gz</code> architectures natively via <code>ubuntu-22.04</code> and <code>mold</code>.</li></ol><h3 id="triggering-a-release" tabindex="-1">Triggering a Release <a class="header-anchor" href="#triggering-a-release" aria-label="Permalink to &quot;Triggering a Release&quot;">​</a></h3><p>Every time you push an annotated git tag prefixed with <code>v</code> (e.g. <code>v0.2.1-pre11</code>), the pipeline boots up, builds the entire Rust application across all OS architectures, and uploads the artifacts as pristine GitHub Assets on the Releases page instantly.</p>',7)])])}const m=t(i,[["render",o]]);export{h as __pageData,m as default};
